// You are given an array arr of integers and you need to return
// sum of magnitudes of integers multiplied by product of all signs
// of each number in the array, represented by 1, -1 or 0.
// Note: return nil for empty arr.
// 
// Example:
// >>> ProdSigns([1, 2, 2, -4]) == -9
// >>> ProdSigns([0, 1]) == 0
// >>> ProdSigns([]) == nil
func ProdSigns(arr []int) interface{} {
	if len(arr) == 0 {
		return nil
	}

	sumMagnitudes := 0
	productSigns := 1

	for _, val := range arr {
		// Calculate magnitude (absolute value)
		sumMagnitudes += int(math.Abs(float64(val)))

		// Determine sign: 1 if positive, -1 if negative, 0 if zero
		sign := 0
		if val > 0 {
			sign = 1
		} else if val < 0 {
			sign = -1
		}

		productSigns *= sign
	}

	return sumMagnitudes * productSigns
}
