To find the minimum sum of a non-empty subarray, you can use a variation of **Kadane's Algorithm**. While the standard Kadane's is used to find the *maximum* subarray sum, you simply flip the logic to track the *minimum* current sum.

Here is the complete implementation:

```java
import java.util.*;
import java.lang.*;

class Solution {
    /**
    Given an array of integers nums, find the minimum sum of any non-empty sub-array
    of nums.
    Example
    minSubArraySum(Arrays.asList(2, 3, 4, 1, 2, 4)) == 1
    minSubArraySum(Arrays.asList(-1, -2, -3)) == -6
     */
    public int minSubArraySum(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            throw new IllegalArgumentException("Input list must not be empty");
        }

        // Initialize currentMin and globalMin with the first element
        int currentMin = nums.get(0);
        int globalMin = nums.get(0);

        for (int i = 1; i < nums.size(); i++) {
            int num = nums.get(i);

            // At each step, decide: 
            // Start a new subarray at the current element, 
            // or extend the existing minimum subarray.
            currentMin = Math.min(num, currentMin + num);

            // Update the global minimum found so far
            globalMin = Math.min(globalMin, currentMin);
        }

        return globalMin;
    }

    public static void main(String[] args) {
        Solution sol = new Solution();
        System.out.println(sol.minSubArraySum(Arrays.asList(2, 3, 4, 1, 2, 4))); // Output: 1
        System.out.println(sol.minSubArraySum(Arrays.asList(-1, -2, -3)));       // Output: -6
        System.out.println(sol.minSubArraySum(Arrays.asList(1, -1, 2, -3, 4)));  // Output: -3
    }
}
```

