func Bf(planet1, planet2 string) []string {
	planets := []string{"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"}

	// Find indices of the two planets
	idx1, idx2 := -1, -1
	for i, p := range planets {
		if p == planet1 {
			idx1 = i
		}
		if p == planet2 {
			idx2 = i
		}
	}

	// Return empty slice if either planet is not found
	if idx1 == -1 || idx2 == -1 {
		return []string{}
	}

	// Determine start and end indices for slicing
	start, end := idx1, idx2
	if idx1 > idx2 {
		start, end = idx2, idx1
	}

	// The planets "between" are from start + 1 up to (but not including) end
	if start+1 >= end {
		return []string{}
	}

	// Create a result slice to avoid modifying the original planets list
	result := make([]string, 0)
	for i := start + 1; i < end; i++ {
		result = append(result, planets[i])
	}

	return result
}
